import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        // (capacity, index) sorted: the first entry of each capacity holds its smallest index.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = nextLong() * n + i;
        Arrays.sort(key);
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < m; t++) {
            long w = nextLong();
            // First entry with capacity > w.
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (key[mid] / n <= w) lo = mid + 1; else hi = mid;
            }
            out.append(lo == n ? -1 : key[lo] % n).append(t + 1 == m ? '\n' : ' ');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"sort"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(nextInt()), int(nextInt())
	// (capacity, index) sorted: the first entry of each capacity holds its smallest index.
	type truck struct {
		capacity int64
		index    int
	}
	trucks := make([]truck, n)
	for i := range trucks {
		trucks[i] = truck{nextInt(), i}
	}
	slices.SortFunc(trucks, func(x, y truck) int {
		if x.capacity != y.capacity {
			if x.capacity < y.capacity {
				return -1
			}
			return 1
		}
		return x.index - y.index
	})
	var out []byte
	for t := 0; t < m; t++ {
		w := nextInt()
		j := sort.Search(n, func(i int) bool { return trucks[i].capacity > w })
		if j < n {
			out = strconv.AppendInt(out, int64(trucks[j].index), 10)
		} else {
			out = append(out, "-1"...)
		}
		if t+1 == m {
			out = append(out, '\n')
		} else {
			out = append(out, ' ')
		}
	}
	os.Stdout.Write(out)
}
